static const int32 GM1LevelPanelTableCount = UE_ARRAY_COUNT(GM1LevelPanelTable);

static TArrayView<const FM1Panel> M1PanelsForLevel(const FString& MapName)
{
	for (const FM1LevelPanels& Level : GM1LevelPanelTable)
	{
		if (MapName.Contains(Level.LevelName, ESearchCase::IgnoreCase))
		{
			return TArrayView<const FM1Panel>(Level.Panels, Level.Count);
		}
	}
	return TArrayView<const FM1Panel>();
}
